function shelf(v){const view=threadSheetsView(v.book),total=view.items.length;if(v.page===null){const last=view.items.findLast(r=>r.readable);v.page=Math.floor((last?.index??Math.max(0,total-1))/8);}v.page=Math.max(0,Math.min(v.page,Math.max(0,Math.ceil(total/8)-1)));const start=v.page*8;return `<h2 id="tt-title" tabindex="-1">Kept orders</h2>${view.status==='unavailable'?'<p>This saved format stays unchanged in Notes. Your draft exploration is open.</p>':''}${total?`<p>Sheets ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol class="tt-shelf" start="${start+1}">${view.items.slice(start,start+8).map(r=>`<li>${r.readable?button(`data-tt-card="${esc(r.id)}"`,`Sheet ${r.index+1} · ${r.raw.source.title}`):'<p>This earlier sheet is unavailable here. Its original stays unchanged in Notes.</p>'}</li>`).join('')}</ol><div class="tt-actions">${button(`data-tt-page="-1"${start===0?' disabled':''}`,'Earlier sheets')}${button(`data-tt-page="1"${start+8>=total?' disabled':''}`,'Later sheets')}</div>`:view.status==='unavailable'?'':'<p>Keep an order to find it here. Unexpected arrangements are welcome.</p>'}<p id="tt-status" role="status" tabindex="-1"></p>`;}
export function twoThreadsPage(book,owner){const v=state(book,owner);if(v.screen==='card'){const row=threadSheetsView(book).items.find(r=>r.readable&&r.id===v.card),old=v.readonly.get(v.card);if(row&&(!old||old.raw!==row.raw||old.rawBytes!==bytes(row.raw)||old.rawIndex!==row.index)){const a=makeSlot(row.raw.source,row.raw.work),rawBytes=bytes(row.raw);if(old?.rawBytes===rawBytes)for(const key of ['selected','turn','folds','frame','demoSelected','echoUI'])a[key]=clone(old[key]);Object.assign(a,{raw:row.raw,rawBytes,rawIndex:row.index});v.readonly.set(v.card,a);}else if(!row)v.readonly.delete(v.card);}if(v.screen==='draft'&&!current(v)){if(!threadCases.some(c=>c.id===v.active))v.active=threadCases[0].id;if(!v.drafts.has(v.active))v.drafts.set(v.active,makeSlot(makeThreadSource(v.active)));}const a=current(v);return `<section class="tt-page" data-tt-root><header><nav class="tt-actions">${button('data-tt-back','Back to English')}${button('data-tt-draft','Your order')}${button('data-tt-shelf','Kept orders')}${button('data-tt-hear data-speak=""','Hear this page')}</nav><h1 id="tt-heading" tabindex="-1">${esc(T.title)}</h1><p>${esc(T.story)}</p></header>${v.screen==='shelf'?shelf(v):a?activePage(a,v.screen==='card',v.drafts.has(v.copies.get(v.card))):'<h2 id="tt-title" tabindex="-1">This sheet is unavailable here</h2><p>Its original stays unchanged in Notes.</p><p id="tt-status" role="status"></p>'}<details data-tt-chooser${v.chooser?' open':''}><summary>Choose a story</summary><div class="tt-actions">${threadCases.map(c=>button(`data-tt-case="${esc(c.id)}" aria-pressed="${v.screen==='draft'&&v.active===c.id}"`,c.title)).join('')}</div><p>Each unkept draft waits during this English visit.</p></details><footer><p>${esc(a?.turn==='echo'?'Keep the order and connections to return later. Leaving English or reloading loses work that has not been kept. Back to English keeps it waiting during this visit.':T.draftWarning)}</p></footer></section>`;}
function mapWords(s,order){return threadMap(s,order).flatMap(t=>[`${t.label}. Appears at positions ${t.positions.join(', ')}.`,...t.returns.map(r=>`From position ${r.from}, ${r.fromTitle}, returned at position ${r.to}, ${r.toTitle}; ${r.gap} intervening ${r.gap===1?'scene':'scenes'}.`),...(t.returns.length?[]:[T.noReturn])]);}
